import { PASSWORD, USERS, expect, expectStatus, test } from "../../fixtures";

test.describe("vendor lifecycle", () => {
  test(
    "search ignores case and matches part of a name",
    { tag: "@LIF-13" },
    async ({ apiAs }) => {
      // Arrange
      const member = await apiAs("member");
      const uniqueSuffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
      const name = `Zephyrine Cold Storage ${uniqueSuffix}`;

      const created = await member.post("/api/vendors", {
        data: {
          name,
          category: "logistics",
          contact_email: `ops-${uniqueSuffix}@zephyrine.test`,
        },
      });
      const vendor = await expectStatus<{ id: string; name: string }>(created, 201);

      // Act
      const response = await member.get("/api/vendors", {
        params: { q: `COLD stor ${uniqueSuffix}`, limit: 100 },
      });

      // Assert
      const page = await expectStatus<{
        items: { id: string; name: string }[];
        total: number;
      }>(response, 200);
      expect(page.items.map((v) => v.id)).toContain(vendor.id);
    },
  );
});
